
/* this code is generated by Claude, with this prompt : 
You are a Java developer.
 Generate a Java class called ReviewSubmission for a mobile app called YOLO — 
 a platform for Erasmus students to discover local spots in their city. 
 The class should: 1) Allow verified students to submit a review for a spot with a rating (1-5), review text, and university email. 2) Validate the university email, rating, and review text before accepting. 3) Allow browsing reviews by spot name or city. 4) Allow upvoting a review by ID. 5) Return top rated reviews (4 stars and above).
 Include a main method with example data to test it*/ 

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.List;
import java.util.stream.Collectors;

// Represents a single review submitted by a student
class Review {
    private String reviewId;
    private String spotName;
    private String city;
    private String reviewerName;
    private String universityEmail;
    private String reviewText;
    private int rating; // 1 to 5
    private LocalDateTime submittedAt;
    private int upvotes;

    public Review(String reviewId, String spotName, String city, String reviewerName,
                  String universityEmail, String reviewText, int rating) {
        this.reviewId = reviewId;
        this.spotName = spotName;
        this.city = city;
        this.reviewerName = reviewerName;
        this.universityEmail = universityEmail;
        this.reviewText = reviewText;
        this.rating = rating;
        this.submittedAt = LocalDateTime.now();
        this.upvotes = 0;
    }

    public String getReviewId() { return reviewId; }
    public String getSpotName() { return spotName; }
    public String getCity() { return city; }
    public String getReviewerName() { return reviewerName; }
    public String getUniversityEmail() { return universityEmail; }
    public String getReviewText() { return reviewText; }
    public int getRating() { return rating; }
    public int getUpvotes() { return upvotes; }

    public void upvote() { this.upvotes++; }

    @Override
    public String toString() {
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("dd MMM yyyy HH:mm");
        return String.format(
            "--- Review ID: %s ---\n" +
            "Spot: %s (%s)\n" +
            "Reviewer: %s (%s)\n" +
            "Rating: %s\n" +
            "Review: %s\n" +
            "Submitted: %s | Upvotes: %d",
            reviewId, spotName, city,
            reviewerName, universityEmail,
            "★".repeat(rating) + "☆".repeat(5 - rating),
            reviewText,
            submittedAt.format(formatter),
            upvotes
        );
    }
}

// Handles review submission and retrieval logic
class ReviewSubmission {

    private List<Review> reviews;
    private int reviewCounter;

    public ReviewSubmission() {
        this.reviews = new ArrayList<>();
        this.reviewCounter = 1;
    }

    // Validate university email (must end with .edu or .de academic domain)
    private boolean isValidUniversityEmail(String email) {
        return email != null && (email.endsWith(".edu") || email.contains("hs-") || email.contains("uni-"));
    }

    // Validate rating (must be between 1 and 5)
    private boolean isValidRating(int rating) {
        return rating >= 1 && rating <= 5;
    }

    // Validate review text (must not be empty, max 500 chars)
    private boolean isValidReviewText(String text) {
        return text != null && !text.trim().isEmpty() && text.length() <= 500;
    }

    // Submit a new review
    public String submitReview(String spotName, String city, String reviewerName,
                                String universityEmail, String reviewText, int rating) {

        if (!isValidUniversityEmail(universityEmail)) {
            return "ERROR: Invalid university email address.";
        }
        if (!isValidRating(rating)) {
            return "ERROR: Rating must be between 1 and 5.";
        }
        if (!isValidReviewText(reviewText)) {
            return "ERROR: Review text is empty or exceeds 500 characters.";
        }

        String reviewId = "REV-" + String.format("%03d", reviewCounter++);
        Review review = new Review(reviewId, spotName, city, reviewerName,
                                   universityEmail, reviewText, rating);
        reviews.add(review);
        return "SUCCESS: Review submitted! ID: " + reviewId;
    }

    // Get all reviews for a specific spot
    public List<Review> getReviewsBySpot(String spotName) {
        return reviews.stream()
                .filter(r -> r.getSpotName().equalsIgnoreCase(spotName))
                .collect(Collectors.toList());
    }

    // Get all reviews for a specific city
    public List<Review> getReviewsByCity(String city) {
        return reviews.stream()
                .filter(r -> r.getCity().equalsIgnoreCase(city))
                .collect(Collectors.toList());
    }

    // Get top rated reviews (4 stars and above)
    public List<Review> getTopRatedReviews() {
        return reviews.stream()
                .filter(r -> r.getRating() >= 4)
                .sorted((a, b) -> b.getRating() - a.getRating())
                .collect(Collectors.toList());
    }

    // Upvote a review by ID
    public String upvoteReview(String reviewId) {
        return reviews.stream()
                .filter(r -> r.getReviewId().equals(reviewId))
                .findFirst()
                .map(r -> { r.upvote(); return "SUCCESS: Upvoted review " + reviewId; })
                .orElse("ERROR: Review not found.");
    }

    public static void main(String[] args) {

        ReviewSubmission rs = new ReviewSubmission();

        // Test 1: Submit valid reviews
        System.out.println("=== Submitting Reviews ===");
        System.out.println(rs.submitReview("Palmengarten", "Frankfurt", "Sofia Wagner",
                "sofia@hs-heilbronn.de", "The best spot to escape the exam stress. Free with student ID!", 5));
        System.out.println(rs.submitReview("The Tiny Cup", "Frankfurt", "Chaewon Bak",
                "chaewon@hs-heilbronn.de", "Cozy and affordable. Great coffee and student-friendly prices.", 4));
        System.out.println(rs.submitReview("Kaffee Mitte", "Heilbronn", "Sofia Wagner",
                "sofia@hs-heilbronn.de", "Lovely little cafe, perfect for studying in the afternoon.", 4));
        System.out.println(rs.submitReview("Palmengarten", "Frankfurt", "Marcus Chen",
                "marcus@hs-heilbronn.de", "Beautiful garden, great place to relax between classes.", 5));

        // Test 2: Submit invalid review (bad email)
        System.out.println("\n=== Invalid Submission (bad email) ===");
        System.out.println(rs.submitReview("Palmengarten", "Frankfurt", "Random User",
                "random@gmail.com", "Nice place!", 4));

        // Test 3: Submit invalid review (bad rating)
        System.out.println("\n=== Invalid Submission (bad rating) ===");
        System.out.println(rs.submitReview("Palmengarten", "Frankfurt", "Sofia Wagner",
                "sofia@hs-heilbronn.de", "Amazing!", 6));

        // Test 4: Get reviews by spot
        System.out.println("\n=== Reviews for Palmengarten ===");
        rs.getReviewsBySpot("Palmengarten").forEach(System.out::println);

        // Test 5: Get reviews by city
        System.out.println("\n=== Reviews in Frankfurt ===");
        rs.getReviewsByCity("Frankfurt").forEach(r ->
                System.out.println(r.getReviewerName() + " — " + r.getRating() + "★ — " + r.getReviewText()));

        // Test 6: Upvote a review
        System.out.println("\n=== Upvoting REV-001 ===");
        System.out.println(rs.upvoteReview("REV-001"));
        System.out.println(rs.upvoteReview("REV-001"));

        // Test 7: Top rated reviews
        System.out.println("\n=== Top Rated Reviews ===");
        rs.getTopRatedReviews().forEach(r ->
                System.out.println(r.getSpotName() + " — " + r.getRating() + "★ — " + r.getReviewerName()));
    }
}

